import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.BxrwG5q5.js";const g=JSON.parse('{"title":"Scheduling","description":"","frontmatter":{},"headers":[],"relativePath":"features/scheduling.md","filePath":"features/scheduling.md"}'),r={name:"features/scheduling.md"};function s(l,e,o,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="scheduling" tabindex="-1">Scheduling <a class="header-anchor" href="#scheduling" aria-label="Permalink to &quot;Scheduling&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/features/prerequisites.html">Prerequisites</a> · <a href="/config/features/environments.html">Environments</a></p></blockquote><p>Scheduling is <strong>timed release</strong> — a flag switches to a new value at a precise date and time without any code deploy or manual intervention. Perfect for planned launches, marketing campaigns, and coordinated multi-environment releases.</p><p>Schedules sit between overrides and <a href="/config/features/targeting.html">targeting rules</a> in the evaluation pipeline.</p><h2 id="dark-launch" tabindex="-1">Dark Launch <a class="header-anchor" href="#dark-launch" aria-label="Permalink to &quot;Dark Launch&quot;">​</a></h2><p>A common pattern is to deploy code with the feature behind a <code>false</code> flag (so it&#39;s in production but unreachable by users), then schedule the activation. This is a <strong>dark launch</strong> — code ships decoupled from feature availability. The schedule is the activation moment.</p><h2 id="setting-up-a-schedule" tabindex="-1">Setting Up a Schedule <a class="header-anchor" href="#setting-up-a-schedule" aria-label="Permalink to &quot;Setting Up a Schedule&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Schedule</strong> section</li><li>Pick a date and time</li><li>Set the target value (what the flag becomes at that time)</li><li>Save</li></ol><h2 id="schedule-behavior" tabindex="-1">Schedule Behavior <a class="header-anchor" href="#schedule-behavior" aria-label="Permalink to &quot;Schedule Behavior&quot;">​</a></h2><p>Schedules are <strong>one-shot activations</strong> — once <code>activateAt</code> is reached, the scheduled value is permanently active until you explicitly change it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>now &gt;= activateAt → return targetValue</span></span>
<span class="line"><span>now &lt;  activateAt → skip, continue to targeting/rollout/default</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">One-shot, not time-windowed</p><p>A schedule does NOT auto-revert. Think of it as &quot;switch to this value at this time, forever.&quot; For time-limited features, set a reminder to manually revert after the event, or use a kill switch flag.</p></div><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>How</th></tr></thead><tbody><tr><td><strong>Timed launch</strong></td><td>Schedule flag to <code>true</code> at launch time — ship code now, release on schedule</td></tr><tr><td><strong>Dark launch</strong></td><td>Deploy behind <code>false</code>, schedule activation — decouple deploy from release</td></tr><tr><td><strong>Marketing campaign</strong></td><td>Schedule config value change at campaign start</td></tr><tr><td><strong>Coordinated release</strong></td><td>Schedule the same flag across environments in sequence (staging first, then prod)</td></tr><tr><td><strong>Deprecation deadline</strong></td><td>Schedule a breaking value change after a migration window closes</td></tr></tbody></table><h2 id="evaluation-priority" tabindex="-1">Evaluation Priority <a class="header-anchor" href="#evaluation-priority" aria-label="Permalink to &quot;Evaluation Priority&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prerequisites → Overrides → Schedule → Targeting → Rollout → Default</span></span></code></pre></div><ul><li>User overrides still take priority over schedules</li><li>Once active, a schedule overrides targeting rules and rollout percentage</li></ul><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Scheduled times are stored in UTC. The portal picker shows your local timezone.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Active schedules override targeting in the pipeline</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Schedule a canary activation at a specific time</li><li><a href="/config/features/prerequisites.html">Prerequisites</a> — Guard flags must pass before a schedule takes effect</li><li><a href="/config/features/audit-log.html">Audit Log</a> — Track when schedules were created and activated</li><li><a href="/config/features/environments.html">Environments</a> — Schedule independently per environment for staged rollouts</li></ul>`,21)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
